import { business, offices } from '../data/catalogue';

export interface Crumb {
  label: string;
  href?: string;
}

/** Shared 1200×630 social preview image (generated by scripts/generate-brand-icons.py). */
export const OG_IMAGE = {
  src: '/images/brand/og-image.jpg',
  width: 1200,
  height: 630,
  alt: 'VALLIS — precision-engineered architectural hardware for luxury spaces',
};

const ORG_ID = `${business.origin}/#organization`;
const WEBSITE_ID = `${business.origin}/#website`;

/**
 * Whether pages may be indexed.
 * - On Vercel, only the Production deployment is indexable; Preview/Development builds are noindex.
 * - Elsewhere (local builds, CI), set PUBLIC_INDEXABLE=false to force noindex.
 */
export function isIndexable(noindex = false): boolean {
  if (noindex) return false;
  const vercelEnv = process.env.VERCEL_ENV;
  if (vercelEnv) return vercelEnv === 'production';
  return (process.env.PUBLIC_INDEXABLE ?? import.meta.env.PUBLIC_INDEXABLE) !== 'false';
}

/** Appends the brand unless the title already names it. */
export function pageTitle(title: string): string {
  return title.includes(business.name) ? title : `${title} | ${business.name}`;
}

/** JSON for a <script type="application/ld+json"> block, with "<" escaped so it can never close the tag. */
export function jsonLd(data: unknown): string {
  return JSON.stringify(data).replace(/</g, '\\u003c');
}

export function siteGraph(): Record<string, unknown>[] {
  const [india] = offices;
  return [
    {
      '@type': ['Organization', 'HardwareStore'],
      '@id': ORG_ID,
      name: business.name,
      legalName: business.company,
      description:
        'VALLIS delivers precision-engineered architectural hardware and seamless smart access solutions for luxury residential, hospitality and commercial spaces.',
      url: `${business.origin}/`,
      logo: { '@type': 'ImageObject', url: `${business.origin}/images/brand/vallis-logo-square-512.png`, width: 512, height: 512 },
      image: `${business.origin}${OG_IMAGE.src}`,
      telephone: business.tel,
      email: business.email,
      address: {
        '@type': 'PostalAddress',
        streetAddress: 'A14/15, Golf Course Rd, DLF Phase 1',
        addressLocality: 'Gurugram',
        addressRegion: 'Haryana',
        postalCode: '122002',
        addressCountry: 'IN',
      },
      hasMap: india.maps,
      contactPoint: [
        { '@type': 'ContactPoint', telephone: business.tel, email: business.email, contactType: 'sales', areaServed: 'IN', availableLanguage: ['en', 'hi'] },
        { '@type': 'ContactPoint', telephone: offices[1].tel, contactType: 'sales', areaServed: 'AE', availableLanguage: ['en'] },
      ],
    },
    {
      '@type': 'WebSite',
      '@id': WEBSITE_ID,
      url: `${business.origin}/`,
      name: business.name,
      inLanguage: 'en-IN',
      publisher: { '@id': ORG_ID },
    },
  ];
}

export function breadcrumbSchema(crumbs: Crumb[], currentUrl: string): Record<string, unknown> {
  const items = [{ label: 'Home', href: '/' }, ...crumbs];
  return {
    '@type': 'BreadcrumbList',
    itemListElement: items.map((c, i) => ({
      '@type': 'ListItem',
      position: i + 1,
      name: c.label,
      item: c.href ? new URL(c.href, business.origin).href : currentUrl,
    })),
  };
}
